// Offline-aware request queue.
//
// Uses @capacitor/network (web implementation) to track connectivity.
// The web implementation derives connectivity from window 'online'/'offline'
// events, which is exactly what the verifier toggles through the browser's
// offline emulation.

import { Network } from '@capacitor/network';

// Internal state
const state = {
  // FIFO of queued request items: { id, body, failTimes, resolve, reject }
  // resolve/reject are kept so callers can await the eventual outcome, but
  // the public surface is not required to expose them.
  queue: [],
  // Latest known connectivity, as reported by Network.getStatus() or a
  // 'networkStatusChange' event.
  connected: true,
  // Set to true when a flush is already in progress, so a reconnect event
  // triggered mid-flush does not start a second concurrent flush.
  flushing: false,
  // Disposer for the networkStatusChange listener.
  removeListener: null,
  // Tracks the active flush completion so callers that submit() while a
  // flush is in progress can piggy-back on the in-flight flush.
  activeFlush: null,
};

const MAX_ATTEMPTS = 4; // total attempts (initial + 3 retries) per request
const BASE_DELAY_MS = 50; // base for exponential backoff

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function backoffDelay(attempt) {
  // attempt is 0-based: 0 -> 50ms, 1 -> 100ms, 2 -> 200ms, ...
  return BASE_DELAY_MS * Math.pow(2, attempt);
}

function isTransientFailure(status, threw) {
  if (threw) return true; // network error
  if (status === 503) return true; // transient server failure
  return false;
}

async function sendOnce(item) {
  // Sends a single attempt; throws on transient failure (network error or 503).
  let response;
  try {
    response = await fetch('/api/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: item.id,
        body: item.body,
        failTimes: typeof item.failTimes === 'number' ? item.failTimes : 0,
      }),
    });
  } catch (err) {
    // Network error (offline mid-flight, DNS, etc.) is treated as transient.
    const wrapped = new Error('network-error');
    wrapped.cause = err;
    throw wrapped;
  }

  if (response.status === 503) {
    throw new Error('transient-503');
  }
  if (!response.ok) {
    // Non-transient failure: do not retry.
    const text = await response.text().catch(() => '');
    const err = new Error(`http-${response.status}`);
    err.body = text;
    err.fatal = true;
    throw err;
  }
  return response;
}

async function sendWithRetry(item) {
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
    try {
      const res = await sendOnce(item);
      // Successful delivery.
      return res;
    } catch (err) {
      const fatal = err && err.fatal;
      const last = attempt === MAX_ATTEMPTS - 1;
      if (fatal || last) {
        throw err;
      }
      // Exponential backoff before the next attempt.
      await delay(backoffDelay(attempt));
    }
  }
  // Unreachable, but keep TypeScript/linters happy.
  throw new Error('unreachable');
}

function findDuplicate(id, body) {
  return state.queue.findIndex(
    (q) => q.id === id && q.body === body,
  );
}

function settleItem(item, outcome, error) {
  if (item.settled) return;
  item.settled = true;
  if (outcome === 'success') {
    item.resolve(true);
  } else {
    item.reject(error || new Error('queue-failed'));
  }
}

async function processItem(item) {
  try {
    await sendWithRetry(item);
    settleItem(item, 'success');
  } catch (err) {
    settleItem(item, 'error', err);
  }
}

async function flushQueue() {
  if (state.flushing) {
    // Coalesce: callers waiting on this same flush will chain on the
    // existing activeFlush promise below.
    return state.activeFlush;
  }
  if (state.queue.length === 0) {
    return;
  }
  state.flushing = true;
  state.activeFlush = (async () => {
    // Strict FIFO: drain in submission order. We snapshot the queue length
    // up front so items added during flushing wait for the next flush.
    // But the requirement is strict FIFO, so we drain one at a time and
    // any new submissions that arrive while flushing wait their turn.
    // Snapshot the current items in FIFO order.
    const items = state.queue.slice();
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      // If connectivity dropped mid-flush, stop and re-queue remaining.
      if (!state.connected) {
        break;
      }
      // Wait for the current item to be settled. processItem handles its
      // own retries with exponential backoff.
      await processItem(item);
    }
  })();
  try {
    await state.activeFlush;
  } finally {
    state.flushing = false;
    state.activeFlush = null;
  }
}

function submit({ id, body, failTimes } = {}) {
  if (typeof id !== 'string' || typeof body !== 'string') {
    return Promise.reject(
      new Error('submit requires { id: string, body: string }'),
    );
  }
  const item = {
    id,
    body,
    failTimes: typeof failTimes === 'number' ? failTimes : 0,
    settled: false,
    resolve: null,
    reject: null,
  };
  const promise = new Promise((resolve, reject) => {
    item.resolve = resolve;
    item.reject = reject;
  });

  // De-duplication: if an identical (id AND body) item is already waiting,
  // do not add a second copy. Return the existing item's promise so the
  // caller still sees the eventual outcome.
  const dupIdx = findDuplicate(id, body);
  if (dupIdx !== -1) {
    return state.queue[dupIdx].promise || promise;
  }

  state.queue.push(item);
  item.promise = promise;

  if (state.connected) {
