    // the loop iterates; but to guarantee strict FIFO across the boundary
    // between already-running and new, we splice into the queue. The
    // current implementation snapshots the queue at flush start, so the
    // new item would be missed. Force a fresh flush once the current one
    // settles to keep ordering correct.
    if (state.flushing) {
      state.activeFlush
        .catch(() => {})
        .then(() => {
          if (state.connected && !item.settled && state.queue.includes(item)) {
            flushQueue().catch(() => {});
          }
        });
    }
  }
  // If offline, the item stays in the queue until the next reconnect.

  return promise;
}

