  // IDs of items that have not been successfully delivered (and not yet
  // given up after retries).
  const out = [];
  for (const item of state.queue) {
    if (!item.settled) {
      out.push(item.id);
    }
  }
  return out;
}

function connected() {
  return state.connected;
}

function onNetworkStatusChange(status) {
  const wasConnected = state.connected;
  state.connected = !!status.connected;
  if (!wasConnected && state.connected) {
    // Reconnect: flush everything still waiting in strict FIFO.
    if (state.queue.length > 0 && !state.flushing) {
      flushQueue().catch(() => {});
    }
  }
}

async function init() {
  // Seed the connectivity from getStatus() so the very first submit() call
  // sees the correct state before the first event fires.
  try {
    const status = await Network.getStatus();
    state.connected = !!status.connected;
  } catch (err) {
    state.connected = true; // optimistic default
  }
  // Register the networkStatusChange listener.
  const handle = await Network.addListener('networkStatusChange', (status) => {
    onNetworkStatusChange(status);
  });
  state.removeListener = handle;
}

const offlineQueue = {
  submit,
  pending,
  connected,
  // Exported for testability, but not part of the public contract.
  _flush: flushQueue,
};

export { offlineQueue, init };

